#!/usr/bin/env python3
"""确定性 TCP/IPv4 报文段构建与解析工具。

子命令：
  segment-build   从 JSON 字段构建 TCP 报文段并计算 Internet 校验和
  segment-parse   从十六进制 TCP 报文段还原字段、选项与负载

契约：
  - 从标准输入读取一个 UTF-8 JSON 对象，成功时向标准输出写一行紧凑 JSON；
  - 错误时向标准错误写一行固定键序的 JSON，且绝不写标准输出；
  - 仅使用 Python 标准库，不联网、不落盘、不读取墙上时钟；
  - 单次最多处理 65535 字节的报文段，时间与额外内存均以报文段长度为线性上界；
  - 相同输入产生逐字节一致的输出。
"""

import argparse
import json
import struct
import sys

MAX_SEGMENT_BYTES = 65535
TCP_HEADER_MIN = 20
TCP_OPTIONS_MAX = 40
IP_PROTO_TCP = 6
# 合法输入的硬上限：65535 字节报文段对应 131070 个十六进制字符，
# 外加字段/选项的 JSON 开销，140000 字节足够且有富余。
MAX_INPUT_BYTES = 140000

FLAG_ORDER = ("urg", "ack", "psh", "rst", "syn", "fin")
FLAG_BITS = {
    "urg": 0x20,
    "ack": 0x10,
    "psh": 0x08,
    "rst": 0x04,
    "syn": 0x02,
    "fin": 0x01,
}

_HEX_DIGITS = frozenset("0123456789abcdefABCDEF")

_BUILD_FIELDS = (
    "src_ip",
    "dst_ip",
    "src_port",
    "dst_port",
    "seq",
    "ack",
    "flags",
    "window",
    "urgent_pointer",
    "options",
    "payload_hex",
)
_PARSE_REQUIRED = ("src_ip", "dst_ip", "segment_hex")
_PARSE_ALLOWED = _PARSE_REQUIRED + ("verify_checksum",)


class ParameterError(Exception):
    """输入 JSON 本身非法（2）。"""


class SegmentFormatError(Exception):
    """报文段结构非法（3）。"""


class ChecksumError(Exception):
    """校验和验证失败（4）。"""


# --------------------------------------------------------------------------- #
# 基础校验
# --------------------------------------------------------------------------- #

def _as_int(name, value, low, high):
    # bool 是 int 的子类，必须显式排除。
    if type(value) is not int:
        raise ParameterError("invalid type: %s" % name)
    if not low <= value <= high:
        raise ParameterError("out of range: %s" % name)
    return value


def _as_bool(name, value):
    if type(value) is not bool:
        raise ParameterError("invalid type: %s" % name)
    return value


def _ipv4_bytes(name, value):
    if not isinstance(value, str):
        raise ParameterError("invalid type: %s" % name)
    parts = value.split(".")
    if len(parts) != 4:
        raise ParameterError("invalid ipv4 address: %s" % name)
    out = bytearray(4)
    for i, part in enumerate(parts):
        # 严格十进制：非 ASCII 数字、空段、前导零一律拒绝。
        if not part or not all("0" <= c <= "9" for c in part):
            raise ParameterError("invalid ipv4 address: %s" % name)
        if len(part) > 1 and part[0] == "0":
            raise ParameterError("invalid ipv4 address: %s" % name)
        number = int(part)
        if number > 255:
            raise ParameterError("invalid ipv4 address: %s" % name)
        out[i] = number
    return bytes(out)


def _as_hex(name, value):
    if not isinstance(value, str) or len(value) % 2 != 0:
        raise ParameterError("invalid hexadecimal text: %s" % name)
    if any(c not in _HEX_DIGITS for c in value):
        raise ParameterError("invalid hexadecimal text: %s" % name)
    return bytes.fromhex(value)


def _validate_flags(value):
    if not isinstance(value, dict):
        raise ParameterError("invalid type: flags")
    if set(value.keys()) != set(FLAG_ORDER):
        raise ParameterError("invalid flags object")
    flags = {}
    for name in FLAG_ORDER:
        flags[name] = _as_bool("flags.%s" % name, value[name])
    return flags


def _check_keys(obj, required, allowed):
    for key in required:
        if key not in obj:
            raise ParameterError("missing field: %s" % key)
    for key in obj:
        if key not in allowed:
            raise ParameterError("unknown field: %s" % key)


# --------------------------------------------------------------------------- #
# 选项
# --------------------------------------------------------------------------- #

def _encode_options(value):
    """返回 (线上字节, 规范化选项 JSON 列表)。"""
    if not isinstance(value, list):
        raise ParameterError("invalid type: options")
    raw = bytearray()
    canonical = []
    ended = False
    for index, item in enumerate(value):
        if ended:
            raise ParameterError("option after end")
        if not isinstance(item, dict):
            raise ParameterError("invalid type: options[%d]" % index)
        if "kind" not in item:
            raise ParameterError("missing field: options[%d].kind" % index)
        kind = item["kind"]
        if kind == "end":
            if tuple(item.keys()) != ("kind",):
                raise ParameterError("unknown field in option: end")
            raw.append(0)
            canonical.append({"kind": "end"})
            ended = True
        elif kind == "nop":
            if tuple(item.keys()) != ("kind",):
                raise ParameterError("unknown field in option: nop")
            raw.append(1)
            canonical.append({"kind": "nop"})
        elif kind == "mss":
            if tuple(item.keys()) != ("kind", "value"):
                raise ParameterError("invalid mss option")
            mss = _as_int(
                "options[%d].value" % index, item["value"], 1, 0xFFFF
            )
            raw += bytes((2, 4)) + struct.pack(">H", mss)
            canonical.append({"kind": "mss", "value": mss})
        else:
            raise ParameterError("unsupported option kind: %r" % (kind,))
    padding = (-len(raw)) % 4
    if len(raw) + padding > TCP_OPTIONS_MAX:
        raise ParameterError("options area exceeds 40 bytes")
    raw += b"\x00" * padding
    return bytes(raw), canonical


def _parse_options(area):
    """解析 TCP 选项区；area 为 data offset 指示的完整选项字节。"""
    options = []
    i = 0
    n = len(area)
    while i < n:
        kind = area[i]
        if kind == 0:
            # End of Option List；其后的零字节仅为对齐填充，不再还原。
            options.append({"kind": "end"})
            break
        if kind == 1:
            options.append({"kind": "nop"})
            i += 1
            continue
        # 其余选项均为 kind(1) + length(1) + data。
        if i + 1 >= n:
            raise SegmentFormatError("truncated tcp option")
        length = area[i + 1]
        if length < 2 or i + length > n:
            raise SegmentFormatError("tcp option length out of range")
        data = area[i + 2:i + length]
        if kind == 2:
            if length != 4:
                raise SegmentFormatError("malformed mss option")
            options.append({"kind": "mss", "value": struct.unpack(">H", data)[0]})
        else:
            options.append({"kind": kind, "data_hex": data.hex()})
        i += length
    return options


# --------------------------------------------------------------------------- #
# 校验和
# --------------------------------------------------------------------------- #

def _internet_checksum(chunks):
    """对若干字节块的逻辑拼接计算 Internet 校验和（线性时间、常数额外内存）。"""
    total = 0
    pending = None  # 上一奇数长度块遗留的字节
    for chunk in chunks:
        if pending is not None and chunk:
            total += (pending << 8) | chunk[0]
            chunk = chunk[1:]
        length = len(chunk)
        end = length - (length & 1)
        if length & 1:
            pending = chunk[end]
        else:
            pending = None
        for i in range(0, end, 2):
            total += (chunk[i] << 8) | chunk[i + 1]
    if pending is not None:
        total += pending << 8  # 奇数长度按 RFC 1071 末尾补零
    while total >> 16:
        total = (total & 0xFFFF) + (total >> 16)
    return (~total) & 0xFFFF


def _pseudo_header(src_ip, dst_ip, tcp_length):
    return struct.pack(
        ">4s4sBBH", src_ip, dst_ip, 0, IP_PROTO_TCP, tcp_length
    )


# --------------------------------------------------------------------------- #
# 子命令
# --------------------------------------------------------------------------- #

def _build_fields(src_ip_text, dst_ip_text, src_ip, dst_ip, obj):
    src_port = _as_int("src_port", obj["src_port"], 0, 0xFFFF)
    dst_port = _as_int("dst_port", obj["dst_port"], 0, 0xFFFF)
    seq = _as_int("seq", obj["seq"], 0, 0xFFFFFFFF)
    ack = _as_int("ack", obj["ack"], 0, 0xFFFFFFFF)
    flags = _validate_flags(obj["flags"])
    window = _as_int("window", obj["window"], 0, 0xFFFF)
    urgent_pointer = _as_int(
        "urgent_pointer", obj["urgent_pointer"], 0, 0xFFFF
    )
    options_bytes, options_json = _encode_options(obj["options"])
    payload = _as_hex("payload_hex", obj["payload_hex"])

    data_offset = (TCP_HEADER_MIN + len(options_bytes)) // 4
    flags_byte = 0
    for name in FLAG_ORDER:
        if flags[name]:
            flags_byte |= FLAG_BITS[name]

    header = struct.pack(
        ">HHIIBBHHH",
        src_port,
        dst_port,
        seq,
        ack,
        data_offset << 4,
        flags_byte,
        window,
        0,  # 校验和先置零
        urgent_pointer,
    )
    segment = bytearray(header + options_bytes + payload)
    if len(segment) > MAX_SEGMENT_BYTES:
        raise ParameterError(
            "segment exceeds %d bytes" % MAX_SEGMENT_BYTES
        )
    pseudo = _pseudo_header(src_ip, dst_ip, len(segment))
    checksum = _internet_checksum([pseudo, bytes(segment)])
    segment[16:18] = struct.pack(">H", checksum)

    fields = {
        "src_ip": src_ip_text,
        "dst_ip": dst_ip_text,
        "src_port": src_port,
        "dst_port": dst_port,
        "seq": seq,
        "ack": ack,
        "flags": {name: flags[name] for name in FLAG_ORDER},
        "window": window,
        "urgent_pointer": urgent_pointer,
    }
    return {
        "operation": "segment-build",
        "segment_hex": bytes(segment).hex(),
        "fields": fields,
        "options": options_json,
        "payload_hex": payload.hex(),
        "checksum_valid": True,
    }


def _parse_fields(src_ip_text, dst_ip_text, src_ip, dst_ip, obj):
    segment = _as_hex("segment_hex", obj["segment_hex"])
    verify = True
    if "verify_checksum" in obj:
        verify = _as_bool("verify_checksum", obj["verify_checksum"])

    if (
        len(segment) < TCP_HEADER_MIN
        or len(segment) > MAX_SEGMENT_BYTES
    ):
        raise SegmentFormatError("segment length out of range")

    (
        src_port,
        dst_port,
        seq,
        ack,
        offset_byte,
        flags_byte,
        window,
        _wire_checksum,
        urgent_pointer,
    ) = struct.unpack(">HHIIBBHHH", segment[:TCP_HEADER_MIN])

    data_offset = offset_byte >> 4
    header_length = data_offset * 4
    if data_offset < 5 or header_length > len(segment):
        raise SegmentFormatError("data offset out of range")

    # 仅建模六个标志位；保留位与 CWR/ECE 不还原，但校验和仍按原始字节计算。
    flags = {
        name: bool(flags_byte & FLAG_BITS[name]) for name in FLAG_ORDER
    }
    options = _parse_options(
        segment[TCP_HEADER_MIN:header_length]
    )
    payload = segment[header_length:]

    checksum_valid = False
    if verify:
        # 标准验证：校验和字段原样参与计算，结果应为 0（RFC 1071）。
        actual = _internet_checksum(
            [_pseudo_header(src_ip, dst_ip, len(segment)), segment]
        )
        if actual != 0:
            raise ChecksumError("tcp checksum mismatch")
        checksum_valid = True

    fields = {
        "src_ip": src_ip_text,
        "dst_ip": dst_ip_text,
        "src_port": src_port,
        "dst_port": dst_port,
        "seq": seq,
        "ack": ack,
        "flags": flags,
        "window": window,
        "urgent_pointer": urgent_pointer,
    }
    return {
        "operation": "segment-parse",
        "segment_hex": segment.hex(),
        "fields": fields,
        "options": options,
        "payload_hex": payload.hex(),
        "checksum_valid": checksum_valid,
    }


# --------------------------------------------------------------------------- #
# 入口
# --------------------------------------------------------------------------- #

def _read_json_object():
    data = sys.stdin.buffer.read(MAX_INPUT_BYTES)
    if len(data) == MAX_INPUT_BYTES and sys.stdin.buffer.read(1):
        raise ParameterError("input exceeds maximum size")
    try:
        text = data.decode("utf-8")
    except UnicodeDecodeError:
        raise ParameterError("invalid json")
    try:
        obj = json.loads(text)
    except json.JSONDecodeError:
        raise ParameterError("invalid json")
    if not isinstance(obj, dict):
        raise ParameterError("input must be a json object")
    return obj


def _run(command, obj):
    if command == "segment-build":
        _check_keys(obj, _BUILD_FIELDS, _BUILD_FIELDS)
        src_ip = _ipv4_bytes("src_ip", obj["src_ip"])
        dst_ip = _ipv4_bytes("dst_ip", obj["dst_ip"])
        return _build_fields(
            obj["src_ip"], obj["dst_ip"], src_ip, dst_ip, obj
        )
    _check_keys(obj, _PARSE_REQUIRED, _PARSE_ALLOWED)
    src_ip = _ipv4_bytes("src_ip", obj["src_ip"])
    dst_ip = _ipv4_bytes("dst_ip", obj["dst_ip"])
    return _parse_fields(
        obj["src_ip"], obj["dst_ip"], src_ip, dst_ip, obj
    )


def _fail(error_name, message):
    sys.stderr.write(
        json.dumps(
            {"error": error_name, "message": message},
            separators=(",", ":"),
            ensure_ascii=False,
        )
        + "\n"
    )


def main(argv=None):
    parser = argparse.ArgumentParser(
        prog="tcp.py",
        description=(
            "确定性 TCP/IPv4 报文段工具：从标准输入读取一个 UTF-8 JSON "
            "对象，向标准输出写一行紧凑 JSON。不联网、不落盘、不读取墙上"
            "时钟；单次最多处理 65535 字节，时间与额外内存均以报文段长度"
            "为线性上界，相同输入逐字节一致。"
        ),
    )
    subparsers = parser.add_subparsers(dest="command", required=True)
    subparsers.add_parser(
        "segment-build",
        description=(
            "构建 TCP/IPv4 报文段：字段经标准输入 JSON 提供，自动确定数据"
            "偏移并按 IPv4 伪首部、TCP 首部与负载计算 Internet 校验和。"
            "选项区零填充至四字节边界且不超过 40 字节，报文段不超过 "
            "65535 字节；时间与额外内存均与报文段长度成线性关系。"
        ),
    )
    subparsers.add_parser(
        "segment-parse",
        description=(
            "解析十六进制 TCP/IPv4 报文段：还原固定键序的字段、选项与负载"
            "，verify_checksum 默认为 true。报文段长度须为 20 至 65535 "
            "字节；时间与额外内存均与报文段长度成线性关系。"
        ),
    )
    args = parser.parse_args(argv)

    try:
        obj = _read_json_object()
        result = _run(args.command, obj)
    except ParameterError as exc:
        _fail("ParameterError", str(exc))
        return 2
    except SegmentFormatError as exc:
        _fail("SegmentFormatError", str(exc))
        return 3
    except ChecksumError as exc:
        _fail("ChecksumError", str(exc))
        return 4

    sys.stdout.write(
        json.dumps(result, separators=(",", ":"), ensure_ascii=False) + "\n"
    )
    return 0


if __name__ == "__main__":
    sys.exit(main())

